import {VERSION} from './catalog.js';import {validateRelease,isNewer,canApply,safeStoreUrl} from './update-model.js';
const workerBuild=worker=>new Promise((resolve,reject)=>{if(!worker)return reject(Error('No worker'));const channel=new MessageChannel(),timeout=setTimeout(()=>{channel.port1.close();reject(Error('Version timeout'));},4000);channel.port1.onmessage=e=>{clearTimeout(timeout);channel.port1.close();resolve(e.data.build);};worker.postMessage({type:'VERSION'},[channel.port2]);});
export class Updates{
 constructor({notify,getRun,save}){this.notify=notify;this.getRun=getRun;this.save=save;this.state='idle';this.release=null;this.reg=null;this.applyRequested=false;this.native=!!globalThis.WispboundNative;this.offlineReady=this.native;this.offlineFailed=false;this.readyWorker=null;globalThis.onNativeUpdate=(data)=>{this.state=data.state;this.progress=data.progress;this.notify();};
  if(!this.native&&'serviceWorker'in navigator){this.registration=navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(r=>{this.reg=r;const refresh=()=>{this.offlineReady=!!r.active;this.notify();};const watch=()=>{const w=r.installing;if(w)w.addEventListener('statechange',()=>{if(w.state==='redundant'&&!r.active)this.offlineFailed=true;refresh();});};r.addEventListener('updatefound',watch);watch();refresh();return r;}).catch(()=>{this.offlineFailed=true;this.notify();return null;});navigator.serviceWorker.addEventListener('controllerchange',()=>{this.offlineReady=true;this.notify();if(this.applyRequested)location.reload();});}else if(!this.native)this.offlineFailed=true;
 }
 set(s){this.state=s;this.notify();}
 async check(){if(this.native){WispboundNative.checkUpdate();return;}this.set('checking');try{const res=await fetch('./release.json?t='+Date.now(),{cache:'no-store'});if(!res.ok)throw Error('offline');this.release=validateRelease(await res.json());this.set(isNewer(VERSION.build,this.release)?'available':'current');}catch{this.set('failed');}}
 async download(){if(!canApply(this.getRun()))return this.set('active');if(!this.save())return this.set('saveFailed');if(this.native){WispboundNative.downloadUpdate();return;}if(!this.release)return this.check();if(this.release.channel==='store'){try{location.href=safeStoreUrl(/android/i.test(navigator.userAgent)?this.release.playUrl:this.release.appStoreUrl);}catch{this.set('failed');}return;}this.set('downloading');try{await this.registration;if(!this.reg)throw Error('No worker');await this.reg.update();const deadline=Date.now()+45000;let candidate;while(Date.now()<deadline){candidate=this.reg.waiting||this.reg.active;if(candidate){const build=await workerBuild(candidate);if(build===this.release.build)break;candidate=null;}await new Promise(resolve=>setTimeout(resolve,250));}if(!candidate)throw Error('Update timeout');this.readyWorker=candidate;this.set('ready');}catch{this.set('failed');}}
 apply(){if(!canApply(this.getRun()))return this.set('active');if(!this.save())return this.set('saveFailed');if(this.native){WispboundNative.installUpdate();return;}if(this.state!=='ready'||!this.readyWorker)return;this.applyRequested=true;if(this.readyWorker.state==='activated')location.reload();else this.readyWorker.postMessage({type:'APPLY'});}
}
